-- Migrazione incrementale: attivitÃ  condivise. Non elimina dati esistenti.
create table public.area_activities (
 id uuid primary key default gen_random_uuid(),area_id uuid not null references public.areas(id) on delete cascade,title text not null check(char_length(btrim(title))>0),notes text,activity_type text not null check(activity_type in('task','reminder','deadline','appointment')),status text not null default 'open' check(status in('open','completed','cancelled')),priority text not null default 'normal' check(priority in('low','normal','high')),starts_at timestamptz,due_at timestamptz,is_all_day boolean not null default false,created_by_profile_id uuid references public.profiles(id) on delete set null,completed_by_profile_id uuid references public.profiles(id) on delete set null,completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint area_activities_dates_check check(starts_at is null or due_at is null or due_at>=starts_at),constraint area_activities_completion_check check((status='completed' and completed_at is not null) or(status<>'completed' and completed_at is null and completed_by_profile_id is null)),unique(id,area_id));
create table public.activity_assignees (activity_id uuid not null,area_id uuid not null,profile_id uuid not null,assigned_at timestamptz not null default now(),assigned_by_profile_id uuid references public.profiles(id) on delete set null,primary key(activity_id,profile_id),foreign key(activity_id,area_id) references public.area_activities(id,area_id) on delete cascade,foreign key(area_id,profile_id) references public.area_memberships(area_id,profile_id) on delete cascade);
create index area_activities_open_due_idx on public.area_activities(area_id,status,due_at) where status='open';
create index area_activities_starts_idx on public.area_activities(area_id,starts_at) where starts_at is not null;
create index area_activities_created_idx on public.area_activities(area_id,created_at desc);
create index activity_assignees_profile_idx on public.activity_assignees(area_id,profile_id,activity_id);
alter table public.area_activities enable row level security; alter table public.activity_assignees enable row level security;
alter table public.area_activities no force row level security; alter table public.activity_assignees no force row level security;
create function public.current_area_activity_role(p_area_id uuid) returns table(profile_id uuid,role text) language sql security definer stable set search_path=public,pg_temp as $$select am.profile_id,am.role from public.area_memberships am join public.profiles p on p.id=am.profile_id where am.area_id=p_area_id and p.user_id=auth.uid() and am.role in('admin','member')$$;
create function public.set_area_activity_updated_at() returns trigger language plpgsql set search_path=public,pg_temp as $$begin new.updated_at=now();return new;end$$;
create trigger area_activities_set_updated_at before update on public.area_activities for each row execute function public.set_area_activity_updated_at();
-- Le sette RPC seguenti sono identiche alle definizioni canoniche in schema.sql;
-- mantenerle sincronizzate quando lo schema viene evoluto.
create function public.get_area_activities(p_area_id uuid,p_status text default null,p_activity_type text default null,p_assigned_to_me boolean default false,p_due_from timestamptz default null,p_due_to timestamptz default null) returns setof public.area_activities language plpgsql security definer set search_path=public,pg_temp as $$declare v uuid;begin select profile_id into v from public.current_area_activity_role(p_area_id);if v is null then raise exception 'permission denied';end if;return query select a.* from public.area_activities a where a.area_id=p_area_id and(p_status is null or a.status=p_status)and(p_activity_type is null or a.activity_type=p_activity_type)and(p_due_from is null or a.due_at>=p_due_from)and(p_due_to is null or a.due_at<=p_due_to)and(not p_assigned_to_me or exists(select 1 from public.activity_assignees x where x.activity_id=a.id and x.profile_id=v)or not exists(select 1 from public.activity_assignees x where x.activity_id=a.id));end$$;
create function public.get_area_activity(p_area_id uuid,p_activity_id uuid) returns public.area_activities language plpgsql security definer set search_path=public,pg_temp as $$declare r public.area_activities;begin if not exists(select 1 from public.current_area_activity_role(p_area_id))then raise exception 'permission denied';end if;select * into r from public.area_activities where id=p_activity_id and area_id=p_area_id;if not found then raise exception 'AttivitÃ  non trovata';end if;return r;end$$;
