create function public.create_area_activity(p_area_id uuid,p_title text,p_notes text,p_activity_type text,p_priority text,p_starts_at timestamptz,p_due_at timestamptz,p_is_all_day boolean,p_assignee_profile_ids uuid[] default '{}') returns uuid language plpgsql security definer set search_path=public,pg_temp as $$declare p uuid;r text;i uuid;v uuid[]:=coalesce(p_assignee_profile_ids,'{}');begin select profile_id,role into p,r from public.current_area_activity_role(p_area_id);if p is null then raise exception 'permission denied';end if;if btrim(coalesce(p_title,''))=''or p_activity_type not in('task','reminder','deadline','appointment')or p_priority not in('low','normal','high')or(p_starts_at is not null and p_due_at is not null and p_due_at<p_starts_at)then raise exception 'Dati attivitÃ  non validi';end if;if r='member'and exists(select 1 from unnest(v)x where x is distinct from p)then raise exception 'permission denied';end if;if exists(select 1 from unnest(v)x left join public.area_memberships m on m.area_id=p_area_id and m.profile_id=x where m.profile_id is null)then raise exception 'Assegnatario non appartenente all''Area';end if;insert into public.area_activities(area_id,title,notes,activity_type,priority,starts_at,due_at,is_all_day,created_by_profile_id)values(p_area_id,btrim(p_title),p_notes,p_activity_type,p_priority,p_starts_at,p_due_at,coalesce(p_is_all_day,false),p)returning id into i;insert into public.activity_assignees(activity_id,area_id,profile_id,assigned_by_profile_id)select i,p_area_id,x,p from(select distinct unnest(v)x)s;return i;end$$;
create function public.update_area_activity(p_area_id uuid,p_activity_id uuid,p_title text,p_notes text,p_activity_type text,p_priority text,p_starts_at timestamptz,p_due_at timestamptz,p_is_all_day boolean)returns void language plpgsql security definer set search_path=public,pg_temp as $$declare p uuid;r text;c uuid;begin select profile_id,role into p,r from public.current_area_activity_role(p_area_id);select created_by_profile_id into c from public.area_activities where id=p_activity_id and area_id=p_area_id;if p is null or not found or(r<>'admin'and c is distinct from p)then raise exception 'permission denied';end if;if btrim(coalesce(p_title,''))=''or p_activity_type not in('task','reminder','deadline','appointment')or p_priority not in('low','normal','high')or(p_starts_at is not null and p_due_at is not null and p_due_at<p_starts_at)then raise exception 'Dati attivitÃ  non validi';end if;update public.area_activities set title=btrim(p_title),notes=p_notes,activity_type=p_activity_type,priority=p_priority,starts_at=p_starts_at,due_at=p_due_at,is_all_day=coalesce(p_is_all_day,false)where id=p_activity_id and area_id=p_area_id;end$$;
create function public.set_area_activity_assignees(p_area_id uuid,p_activity_id uuid,p_assignee_profile_ids uuid[])returns void language plpgsql security definer set search_path=public,pg_temp as $$declare p uuid;r text;v uuid[]:=coalesce(p_assignee_profile_ids,'{}');begin select profile_id,role into p,r from public.current_area_activity_role(p_area_id);if r<>'admin'or not exists(select 1 from public.area_activities where id=p_activity_id and area_id=p_area_id)then raise exception 'permission denied';end if;if exists(select 1 from unnest(v)x left join public.area_memberships m on m.area_id=p_area_id and m.profile_id=x where m.profile_id is null)then raise exception 'Assegnatario non appartenente all''Area';end if;delete from public.activity_assignees where activity_id=p_activity_id and area_id=p_area_id;insert into public.activity_assignees(activity_id,area_id,profile_id,assigned_by_profile_id)select p_activity_id,p_area_id,x,p from(select distinct unnest(v)x)s;end$$;
create function public.set_area_activity_status(p_area_id uuid,p_activity_id uuid,p_status text)returns void language plpgsql security definer set search_path=public,pg_temp as $$declare p uuid;r text;begin select profile_id,role into p,r from public.current_area_activity_role(p_area_id);if p is null or p_status not in('open','completed','cancelled')or not exists(select 1 from public.area_activities where id=p_activity_id and area_id=p_area_id)or(r<>'admin'and(p_status<>'completed'or(exists(select 1 from public.activity_assignees where activity_id=p_activity_id)and not exists(select 1 from public.activity_assignees where activity_id=p_activity_id and profile_id=p))))then raise exception 'permission denied';end if;update public.area_activities set status=p_status,completed_at=case when p_status='completed'then now()else null end,completed_by_profile_id=case when p_status='completed'then p else null end where id=p_activity_id and area_id=p_area_id;end$$;
create function public.delete_area_activity(p_area_id uuid,p_activity_id uuid)returns void language plpgsql security definer set search_path=public,pg_temp as $$declare p uuid;r text;c uuid;s text;begin select profile_id,role into p,r from public.current_area_activity_role(p_area_id);select created_by_profile_id,status into c,s from public.area_activities where id=p_activity_id and area_id=p_area_id;if p is null or not found or(r<>'admin'and(c is distinct from p or s<>'open'))then raise exception 'permission denied';end if;delete from public.area_activities where id=p_activity_id and area_id=p_area_id;end$$;
revoke all on public.area_activities,public.activity_assignees from public,authenticated;
